/// <summary>
/// COC extension class of <c>FreeTextInvoiceController</c> in Metcash model.
/// </summary>

[ExtensionOf(classStr(FreeTextInvoiceController))]
internal final class METFreeTextInvoiceController_Extension
{
}

Method.Source:
/// <summary>
/// Returns report name
/// </summary>
/// <param name = "common"><c>Common</c> record</param>
/// <returns>Report name</returns>
public SRSCatalogItemName getReportName(Common _common)
{
    SRSCatalogItemName ret = next getReportName(_common); 

    CustInvoiceTable custInvoiceTable;
    if (_common.TableId == tableNum(CustInvoiceTable))
    {
        custInvoiceTable = _common;
    }
    else if (_common.TableId == tableNum(CustInvoiceJour))
    {
        CustInvoiceJour custInvoiceJour = _common; 
        custInvoiceTable = CustInvoiceTable::findSourceDocumentHeader(custInvoiceJour.SourceDocumentHeader);
    }

    // Task 226480: Branding details update - Reports - Start
    if (custInvoiceTable && custInvoiceTable.TAMRebateTransId)
    {
        ret = ssrsReportStr(METFreeTextInvoiceRebate, Report); // for lasernet
    }

    return ret;
}

/// <summary>
/// Changes the report contract before the report is run. 
/// Have subsribed to preRunModifyContractExtension delegate called just before super() call of preRunModifyContract() method. So perfomring a check in this 
/// in this extension metod to check for report name.
/// </summary>
protected void preRunModifyContract()
{
    next preRunModifyContract();

    if (this.parmReportName() 
        && contract.parmMETSelectedReportName() != this.parmReportName())
    {
        contract.parmMETSelectedReportName(this.parmReportName());
    }
}

/// <summary>
/// Method to overwrite the print management setting to fetch the custom Rebate Free text invoice report based on Rebate transaction number.
/// </summary>
protected void outputReport()
{
    if(formLetterReport is SalesFormLetterReport_FreeText && custInvoiceJour && custInvoiceJour.METTAMRebateTransId != '')
    {
        SalesFormLetterReport_FreeText formLetterReportLoc = formLetterReport;
        PrintMgmtPrintSettingDetail printDetail = formLetterReport.getCurrentPrintSetting();
        //Ensure the print detail is not null
        if(printDetail)
        {
            printDetail.parmReportFormatName(ssrsReportStr(METFreeTextInvoiceRebate, Report));
            formLetterReportLoc.metSettCurrentPrinterSettings(printDetail);
            formLetterReport = formLetterReportLoc;
        }
    }

    next outputReport();
}
